import re

with open('/home/ctfplayer/welcome2.r2','r') as f:
    lines = f.readlines()

flag_mem = None
hash_mem = None
psz = None
explanations = []
data_movements = []
out_addrs = []

for l in lines:
    if 'f loc.flag' in l:
        mo = re.search(r'f +loc.flag *= *0x([0-9a-fA-F]+)',l)
        if mo:
            flag_mem = int(mo.group(1),16)
            explanations.append(f"Flag buffer @ 0x{flag_mem:x}")
    if 'loc.hash' in l:
        mo = re.search(r'f +loc.hash *= *0x([0-9a-fA-F]+)',l)
        if mo:
            hash_mem = int(mo.group(1),16)
            explanations.append(f"Hash buffer @ 0x{hash_mem:x}")
    if l.strip().startswith('psz '):
        psz = l.split('psz ',1)[1].strip()
        explanations.append(f"psz string used: '{psz}'")
    wxmo = re.match(r'wx ([0-9a-fA-F]+)',l)
    if wxmo:
        payload = wxmo.group(1)
        if len(payload)%2==0 and len(payload)>=8:
            try:
                ascii_guess = bytes.fromhex(payload)
                if all([(c==0) or (c>=32 and c<=126) for c in ascii_guess]):
                    explanations.append(f"Memory write (ascii): {ascii_guess}")
            except Exception as e:
                pass
        data_movements.append(payload)
    if l.strip().startswith('w*'):
        # e.g. w* 0x4008 32
        outs = re.findall(r'0x[0-9a-fA-F]+',l)
        if outs:
            out_addrs.extend([int(a,16) for a in outs])
            explanations.append(f"Output reveal at: {l.strip()}")

