        f.write(f" - Memory label for hash buffer at: 0x{hash_mem:x}\n")
    if psz:
        f.write(f" - psz string: {psz}\n")
    if data_movements:
        f.write(f" - Total memory writes (wx): {len(data_movements)} entries\n")
