import re

def decode_candidates(candidates):
    results = []
    for cand in candidates:
        # Even length: try hex decoding
        if len(cand) % 2 == 0:
            try:
                byte_rep = bytes.fromhex(cand)
                # If all bytes are printable, consider this
                if all(32 <= b <= 126 for b in byte_rep):
                    decoded = byte_rep.decode()
                    results.append((cand, decoded, 'hex'))
            except Exception:
                pass
        # Try treating as decimal ASCII codes, chunked by 2 or 3 digits
        dec_variants = []
        for chunk in (2, 3):
            dec_chars = []
            idx = 0
            while idx < len(cand):
                part = cand[idx:idx+chunk]
                try:
                    num = int(part)
                    if 32 <= num <= 126:
                        dec_chars.append(chr(num))
                        idx += chunk
                    else:
                        break
                except Exception:
                    break
            if len(dec_chars) > 2 and idx == len(cand):
                dec_str = ''.join(dec_chars)
                dec_variants.append(dec_str)
        for v in dec_variants:
            results.append((cand, v, 'decimal'))
    # Remove similar results, keep only most readable by length
    seen = set()
    uniq = []
    for c, v, typ in sorted(results, key=lambda x: len(x[1]), reverse=True):
        key = v.lower()
        if key not in seen:
            seen.add(key)
            uniq.append((c, v, typ))
    return uniq[:3]

def main():
    # Load candidate numbers from file or input (for this challenge, mockup some)
    import sys
    if len(sys.argv) > 1:
        lines = open(sys.argv[1]).readlines()
    else:
        # Hardcoded mockup
        lines = [
            '3136313837', '3535373733', '3135343536', '3133393432',
            '466c61676f',  # Flag as hex
            '10210897103', '1021089797',
            '68656c6c6f',  # hello in hex
        ]
    # Clean and extract digit strings
    candidates = []
    for line in lines:
        candidates.extend(re.findall(r'[0-9a-fA-F]{4,}', line.strip()))
    results = decode_candidates(candidates)
    # Format as flag{...} candidates, print result
    for idx, (orig, val, typ) in enumerate(results):
        flag_fmt = f"flag{{{val}}}"
        print(f"Candidate {idx+1}: {flag_fmt} (from '{orig}', method={typ})")

if __name__ == "__main__":
    main()

